import re,glob
FILES=sorted(glob.glob('src/p*.txt'))
TXT={f:open(f,encoding='utf-8').read() for f in FILES}
def fix(prefix,new):
    for f in FILES:
        t=TXT[f]; i=t.find(prefix)
        if i<0: continue
        m=re.compile(r'\.(?=\s+[A-ZÀ-Ý«<]|</div>|</li>|\n|$)').search(t,i)
        old=t[i:m.end()]
        ids=','.join(dict.fromkeys(x for g in re.findall(r'\^([\w.\-:,]+)\^',old) for x in g.split(',')))
        n=new.replace('{C}','^'+ids+'^') if ids else new.replace('{C}','')
        TXT[f]=t[:i]+n+t[m.end():]; return
    print('MISSING',prefix[:60])
P=[
("Le service de cardiologie des Hôpitaux universitaires de Genève la définit ainsi :","Le service de cardiologie des Hôpitaux universitaires de Genève la définit ainsi. Lorsque la tachycardie naît dans le nœud atrio-ventriculaire, carrefour électrique entre les deux oreillettes et les deux ventricules, on parle de tachycardie par réentrée intranodale{C}."),
("Une tachycardie supraventriculaire est une tachyarythmie qui se traduit","Une tachycardie supraventriculaire est une tachyarythmie qui se traduit par des battements rapides des ventricules, supérieurs à 100 par minute{C}. Elle provient en partie ou complètement de l'extérieur des ventricules, dans les oreillettes ou dans une partie du système de conduction{C}."),
("Piège d'examen : la voie lente n'est pas un faisceau étranger","Piège d'examen : la voie lente ne constitue pas un faisceau étranger au cœur normal, car elle correspond à une extension du nœud lui-même{C}."),
("Les textes suisses emploient indifféremment","Les textes suisses emploient indifféremment « tachycardie par réentrée intranodale » et « tachycardie paroxystique supraventriculaire » pour désigner le tableau clinique. La seconde appellation est aussi celle de l'information professionnelle de l'adénosine{C}."),
("D'abord, la réentrée intranodale n'est pas une tachycardie sinusale","D'abord, la réentrée intranodale ne ressemble pas à une tachycardie sinusale, c'est-à-dire un rythme sinusal rapide qui dépasse 100 battements par minute au repos ou à l'effort minimal{C}."),
("Les formes selon le sens du circuit se définissent","Les formes selon le sens du circuit se définissent par l'intervalle entre l'activation du faisceau de His et celle de l'oreillette. La forme lente-rapide montre un intervalle His-oreillette inférieur ou égal à 70 ms{C}."),
("Aucune enquête suisse de prévalence","Les sources lues ne contiennent aucune enquête suisse de prévalence propre à la réentrée intranodale ; les chiffres ci-dessous viennent donc d'études européennes, puis d'études internationales publiées dans des revues reconnues en Suisse."),
("Aux États-Unis, une étude de prévalence","Aux États-Unis, une étude de prévalence menée dans un grand système de soins chiffre la tachycardie paroxystique supraventriculaire symptomatique à 140 pour 100 000{C}. Cette prévalence est plus élevée chez les personnes âgées, les femmes et celles qui souffrent d'une cardiopathie valvulaire, d'insuffisance cardiaque, de diabète ou de maladie pulmonaire{C}."),
("Le tableau suivant rassemble les principaux chiffres","Le tableau suivant rassemble les principaux chiffres : il indique la population, l'année et la source de chacun."),
("Les femmes sont atteintes environ deux fois","Les femmes sont atteintes environ deux fois plus souvent que les hommes. Une revue de la littérature décrit une prédominance féminine du simple au double, que les auteurs attribuent aux hormones sexuelles et au tonus autonome{C}."),
("Une série turque d'ablation retrouve","Une série turque d'ablation compte 65,8 % de femmes et un âge moyen de 47,2 ans dans le groupe traité par cryoablation{C}."),
("Le résumé de la revue Cochrane précise","Le résumé de la revue Cochrane précise que cette arythmie survient habituellement chez des personnes par ailleurs en bonne santé{C}. Les symptômes courants sont des palpitations, une sensation de tête légère et des douleurs thoraciques{C}."),
("Chez les femmes qui avaient un antécédent","Chez les femmes qui avaient un antécédent, la récidive pendant la grossesse survient chez 68 % d'entre elles{C}. Elle atteint 81 % lorsque l'épisode date de moins de 5 ans, contre 31 % lorsqu'il est plus ancien{C}."),
("Une erreur entre réentrée intranodale et réentrée par voie accessoire change","Une erreur entre réentrée intranodale et réentrée par voie accessoire modifie pourtant le risque en cas de fibrillation auriculaire associée, ainsi que le choix des médicaments{C}."),
("La physiopathologie de la réentrée intranodale se comprend","La physiopathologie de la réentrée intranodale se comprend en trois temps. D'abord, un nœud atrio-ventriculaire normal transmet l'influx. Ensuite, un substrat anatomique permet à l'influx de boucler. Enfin, un déclencheur lance la boucle et un arrêt la rompt."),
("À la pointe du triangle de Koch","À la pointe du triangle de Koch, il reçoit une dernière entrée atriale venant de la partie centrale du septum interauriculaire{C}. Il s'isole ensuite par du tissu fibreux pour devenir le faisceau de His{C}."),
("En effet, la plupart des tachycardies par réentrée intranodale sont interrompues","En effet, la plupart des tachycardies par réentrée intranodale sont interrompues par une ablation au niveau de l'extension inférieure droite^wb0d24f-9^. Le taux de succès de l'ablation de la voie lente ciblant cette extension atteint de 96 % à 98 %^wcacc51-9^."),
("La démonstration de ce substrat en laboratoire repose","La démonstration de ce substrat en laboratoire repose sur le <button class=\"w\" popovertarget=\"dx5-p3-f1\">saut atrio-hissien</button>. La conduction à double voie se définit par un saut de l'intervalle atrio-hissien de plus de 50 ms à la stimulation atriale programmée{C}."),
("Piège d'examen : le saut atrio-hissien ne sert pas","Piège d'examen : le saut atrio-hissien ne suffit pas comme critère de succès de l'ablation, car la disparition de la double voie en fin de procédure ne constitue pas un marqueur spécifique de guérison{C}."),
("La forme lente-rapide domine largement","La forme lente-rapide domine largement, car elle représente 82 % des tachycardies traitées dans une série de patients récidivants{C}. Elle précède la forme rapide-lente (7 %) et la forme lente-lente (4 %){C}."),
("À l'inverse, une étude récente de 126 patients","À l'inverse, une étude récente de 126 patients avec réentrée intranodale typique utilise des extrastimuli atriaux tardifs{C}. La tachycardie est réinitialisée sans modifier le site de la première activation atriale rétrograde dans 96 % des cas{C}. La voie commune supérieure n'est donc suggérée que chez 2,4 % des patients{C}."),
("Piège d'examen : l'association d'un bêtabloquant","Piège d'examen : l'association d'un bêtabloquant et d'un antagoniste calcique par voie intraveineuse provoque une hypotension et une bradycardie sévères{C}."),
("L'intervalle entre le QRS et l'onde P rétrograde est court","L'intervalle entre le QRS et l'onde P rétrograde est court. Dans une série avec dérivation de Lewis, il vaut 88 ± 17 ms pour la réentrée intranodale contre 154 ± 34 ms pour la réentrée par voie accessoire{C}. Un seuil de 100 ms sépare les deux avec une sensibilité de 89 % et une spécificité de 71 %{C}."),
("Dans une autre série, le seuil de 100 ms donne","Dans une autre série, le seuil de 100 ms offre une sensibilité de 89 % et une spécificité de 71 % pour séparer les deux mécanismes{C}."),
("Un rythme sinusal rapide ne se confond pas","Un rythme sinusal rapide ne se confond pas avec la réentrée intranodale. La tachycardie sinusale inappropriée est un rythme sinusal supérieur à 100 par minute au repos ou à l'effort minimal, disproportionné par rapport au stress{C}."),
("Le colloque de médecine de premier recours","Le colloque de médecine de premier recours des Hôpitaux universitaires de Genève sur le bilan des palpitations propose cinq temps de questions{C}. Il s'agit de ce qui précède le début, du <button class=\"w\" popovertarget=\"dx5-p5-f1\">mode de démarrage</button>, du type de palpitations, de la fin de l'épisode et de l'anamnèse générale{C}."),
("La raison physiopathologique est la suivante","La raison physiopathologique est la suivante. Une réentrée démarre quand une extrasystole rencontre une voie encore réfractaire. Elle s'arrête quand un maillon du circuit se bloque, d'où le caractère tout ou rien du rythme."),
("Les comorbidités associées à une charge plus élevée","Les comorbidités associées à une charge plus élevée de tachycardie paroxystique supraventriculaire symptomatique sont l'âge avancé, le sexe féminin et la cardiopathie valvulaire{C}. S'y ajoutent l'insuffisance cardiaque, le diabète, la maladie pulmonaire et les antécédents hémorragiques{C}."),
("La revue des médicaments conditionne","La revue des médicaments conditionne le choix thérapeutique, car plusieurs médicaments modifient l'effet des ralentisseurs nodaux."),
("Exemple clinique : un patient qui a bu du thé","Exemple clinique : un patient qui a bu du thé ou du café peu avant l'injection peut répondre moins bien à la dose habituelle{C}. Un échec ne prouve alors pas que le diagnostic de réentrée est faux{C}."),
("À l'inverse d'une tachycardie, une bradycardie","À l'inverse d'une tachycardie, une bradycardie se reconnaît à un pouls inférieur à 50 par minute pour l'emploi du métoprolol, et inférieur à 55 pour celui du diltiazem{C}."),
("L'examen de l'état de conscience","L'examen de l'état de conscience, de la sudation, de la perfusion cutanée et de la fréquence respiratoire complète les constantes, car ces signes révèlent le retentissement de la crise."),
("La palpation du choc de pointe","La palpation du choc de pointe et la recherche d'un galop complètent l'examen. Une cardiopathie structurelle fait en effet craindre une tachycardie ventriculaire{C}. Les causes les plus fréquentes de celle-ci sont l'infarctus, la cardiomyopathie, la myocardite et les maladies valvulaires{C}."),
("L'auscultation pulmonaire cherche","L'auscultation pulmonaire recherche des sibilants et des crépitants, car ces signes orientent le choix du médicament."),
("Dans l'essai REVERT, le patient est installé","Dans l'essai REVERT, le patient est installé semi-allongé et expire contre une résistance pour atteindre une pression de 40 mm Hg pendant 15 secondes{C}. Il est ensuite immédiatement replacé à plat avec élévation passive des jambes{C}."),
("Dans l'essai REVERT, mené chez 433 adultes","Dans l'essai REVERT, mené chez 433 adultes aux urgences, le retour au rythme sinusal à une minute est obtenu chez 43 % des patients avec la manœuvre modifiée{C}. Il l'est chez 17 % avec la manœuvre standard, avec un rapport de cotes ajusté de 3,7{C}."),
("Le consensus européen cite les manœuvres vagales","Le consensus européen cite les manœuvres vagales, le massage carotidien et l'adénosine intraveineuse comme moyens de répondre à une tachycardie paroxystique supraventriculaire{C}, ce qui place le massage parmi les gestes de première ligne."),
("Piège d'examen : une réponse partielle au massage","Piège d'examen : une réponse partielle au massage ne dispense pas de l'adénosine, car l'adénosine reste le médicament de choix quand les manœuvres vagales échouent{C}."),
("La dérivation de Lewis aide à repérer","La dérivation de Lewis aide à repérer l'activité atriale. Elle place une électrode sur le bord droit du sternum au deuxième espace intercostal à la place du bras droit{C}. Elle place aussi une électrode au quatrième espace intercostal à la place du bras gauche{C}."),
("Dans l'étude, l'intervalle RP vaut","Dans l'étude, l'intervalle RP vaut 88 ± 17 ms pour la réentrée intranodale typique contre 154 ± 34 ms pour la réentrée par voie accessoire{C}. Le seuil de 100 ms offre une sensibilité de 89 % et une spécificité de 71 %{C}."),
("Piège d'examen : l'onde P n'est visible","Piège d'examen : l'onde P reste visible dans 66 % des cas seulement avec cette dérivation{C}. Ainsi, l'absence d'onde P n'écarte pas la réentrée intranodale."),
("Le geste de recherche est le décompte des épisodes","Le geste de recherche est le décompte des épisodes sur les mois précédents. L'essai randomisé qui compare ablation et antiarythmiques inclut des patients ayant au moins un épisode symptomatique par mois{C}. Les hospitalisations pour cardioversion y sont significativement moins nombreuses après ablation{C}."),
("Chez le patient traité par vérapamil, des bradyarythmies","Chez le patient traité par vérapamil, des bradyarythmies peuvent survenir, surtout à forte dose ou en cas de lésions préexistantes{C}. Il s'agit de la bradycardie sinusale, de l'arrêt sinusal avec asystolie et du bloc atrio-ventriculaire du deuxième ou du troisième degré{C}."),
("Le tableau suivant résume les cinq syndromes","Le tableau suivant résume les cinq syndromes, car chacun associe des signes fonctionnels et des signes physiques."),
("Aucune des sources lues ne propose","Aucune des sources lues ne propose de critères majeurs et mineurs chiffrés comme pour une maladie systémique ; les seuils ci-dessous sont ceux des travaux cités avec leur année."),
("Le service de cardiologie des Hôpitaux universitaires de Genève décrit la tachycardie supraventriculaire comme","Le service de cardiologie des Hôpitaux universitaires de Genève décrit la tachycardie supraventriculaire comme une tachyarythmie avec des battements ventriculaires rapides, au-dessus de 100 par minute{C}. Cette arythmie naît en partie ou complètement hors des ventricules{C}."),
("Le tableau ci-dessous donne les seuils","Le tableau ci-dessous donne les seuils retrouvés dans les séries d'électrophysiologie, car ces seuils guident le diagnostic de mécanisme."),
("La conduction à double voie se définit par un saut atrio-hissien","La conduction à double voie se définit par un saut atrio-hissien de plus de 50 ms à la stimulation atriale programmée{C}. La tachycardie est induite par stimulation programmée, par salve atriale ou par isoprénaline{C}."),
("Les trois formes se classent par l'intervalle His-oreillette","Les trois formes se classent par l'intervalle His-oreillette. La forme lente-rapide présente au plus 70 ms{C}. La forme rapide-lente dépasse 70 ms, avec un rapport atrio-hissien sur hissio-atrial inférieur à 1 et un intervalle atrio-hissien inférieur à 200 ms{C}. La forme lente-lente dépasse aussi 70 ms, avec un rapport supérieur à 1 et un intervalle atrio-hissien supérieur à 200 ms{C}."),
("Des manœuvres de stimulation sont employées","Des manœuvres de stimulation sont employées pour exclure une voie nodo-ventriculaire ou nodo-fasciculaire cachée. L'entraînement ventriculaire avec un intervalle post-stimulation corrigé moins la longueur de cycle supérieur à 110 ms oriente vers la réentrée intranodale{C}."),
("La réentrée intranodale ne dispose d'aucun score","La réentrée intranodale n'a aucun score ni aucun stade validé dans les sources lues. La gravité dépend donc de la tolérance, de la fréquence des épisodes et de la cardiopathie sous-jacente{C}."),
("Le diagnostic final de réentrée intranodale, de réentrée par voie accessoire","Le diagnostic final de réentrée intranodale, de réentrée par voie accessoire ou de tachycardie atriale se confirme par l'<button class=\"w\" popovertarget=\"dx5-p9-f1\">étude électrophysiologique</button>{C}. Dans les séries de référence, elle sert de critère de comparaison pour les signes électrocardiographiques{C}."),
("Au départ, les intervalles atrio-hissien","Au départ, les intervalles atrio-hissien et hisso-ventriculaire sont enregistrés et la conduction à double voie est recherchée{C}. Ensuite, la tachycardie est induite par stimulation programmée ou par salve atriale, avec de l'isoprénaline en cas d'échec{C}."),
("L'adénosine n'a pas d'effet sur la fibrillation","L'adénosine reste sans effet sur la fibrillation et sur le flutter auriculaires, car le nœud n'y participe pas{C}."),
("La dérivation de Lewis rend l'onde P positive","La dérivation de Lewis rend l'onde P positive visible dans 66 % des enregistrements{C}. Les dérivations standard la montrent dans 45 % des cas{C}."),
("Si le patient est stable, alors un électrocardiogramme","Si le patient est stable, alors un électrocardiogramme de crise est enregistré et comparé au tracé de base{C}."),
("Si le QRS est large ou si une cardiopathie","Si le QRS est large ou si une cardiopathie structurelle est connue, alors une tachycardie ventriculaire est présumée{C}. Dans ce cas, le vérapamil et le diltiazem sont évités{C}."),
("Si le QRS est fin, régulier et rapide","Si le QRS est fin, régulier et rapide, alors une tachycardie supraventriculaire est retenue."),
("Si l'intervalle RP est inférieur à 70 ms","Si l'intervalle RP est inférieur à 70 ms avec un pseudo-r' en V1, alors la réentrée intranodale est le diagnostic le plus probable{C}."),
("Si le diagnostic est une tachycardie supraventriculaire stable","Si le diagnostic est une tachycardie supraventriculaire stable, alors une manœuvre vagale est réalisée en premier{C}. Elle se pratique de préférence en décubitus dorsal avec élévation des jambes{C}."),
("Si la manœuvre échoue et qu'aucune préexcitation","Si la manœuvre échoue et qu'aucune préexcitation n'existe, alors l'adénosine intraveineuse est administrée{C}. Elle se donne en milieu hospitalier sous monitorage{C}."),
("Si la crise est terminée, alors le choix","Si la crise est terminée, alors le choix du traitement de fond dépend de la fréquence et du retentissement."),
("Si les crises sont symptomatiques et récidivantes","Si les crises sont symptomatiques et récidivantes, alors l'ablation de la voie lente est recommandée avec le niveau de classe I{C}."),
("Si la patiente est enceinte, alors tous","Si la patiente est enceinte, alors tous les antiarythmiques sont évités si possible pendant le premier trimestre{C}."),
("Si une prévention est nécessaire hors syndrome","Si une prévention est nécessaire hors syndrome de Wolff-Parkinson-White, alors un bêtabloquant bêta-1 sélectif, sauf l'aténolol, est considéré en premier{C}. Le vérapamil vient ensuite dans cet ordre{C}."),
("En urgence, il vise le retour au rythme sinusal","En urgence, il vise le retour au rythme sinusal. Dans sept essais réunissant 622 participants, les taux de retour au rythme sinusal sont de 89,7 % avec l'adénosine{C}. Ils sont de 92,9 % avec les inhibiteurs calciques{C}."),
("À distance, il vise la guérison par l'ablation","À distance, il vise la guérison par l'ablation. Son taux de succès est de 97 %, avec une récidive de 1,3 % à 4 % et un risque de bloc atrio-ventriculaire inférieur à 1 %{C}."),
("En cas de tachycardie stable, la manœuvre de Valsalva modifiée est essayée","En cas de tachycardie stable, la manœuvre de Valsalva modifiée est essayée{C}. Elle comprend un effort expiratoire de 15 secondes à une pression de 40 mm Hg, puis un décubitus dorsal avec élévation passive des jambes{C}. Elle ramène le rythme sinusal chez 43 % des patients à une minute^w43c063-5,w43c063-7^."),
("Aucune dose supplémentaire n'est administrée si la première","Aucune dose supplémentaire n'est administrée si la première a provoqué une hypotension symptomatique{C}. Il en va de même après une bradycardie ou une asystolie sévère, ou après un trouble du rythme ou de la conduction de degré élevé{C}."),
("Le choix entre adénosine et inhibiteurs calciques n'est pas tranché","Le choix entre adénosine et inhibiteurs calciques ne dépend pas de l'efficacité, car la revue Cochrane ne trouve pas de différence de retour au rythme sinusal entre eux{C}. Le rapport de cotes est de 1,51 et l'intervalle de confiance à 95 % va de 0,85 à 2,68{C}."),
("L'efficacité de l'adénosine dépend toutefois","L'efficacité de l'adénosine dépend toutefois de la fréquence, car la probabilité d'arrêt dépasse 75 % au-dessus de 166 battements par minute et tombe à 25 % à 138 par minute{C}."),
("Classe : nucléoside purique","Classe : l'adénosine est un nucléoside purique à effet dromotrope négatif sur le nœud atrio-ventriculaire, de code ATC C01EB10{C}."),
("Posologie : 6 mg puis 12 mg, voie intraveineuse","Posologie : l'adulte reçoit 6 mg puis 12 mg par voie intraveineuse en bolus de 2 secondes, sans jamais de dose supplémentaire{C}."),
("Contre-indications : bloc atrio-ventriculaire de second ou troisième degré sans stimulateur","Contre-indications : elles comprennent le bloc atrio-ventriculaire de second ou troisième degré sans stimulateur, le syndrome du sinus malade, la bradycardie symptomatique et l'hypersensibilité{C}. Elles comprennent aussi l'affection pulmonaire obstructive chronique comme l'asthme, le syndrome du QT long, l'hypotension sévère et l'insuffisance cardiaque décompensée{C}."),
("Effets indésirables très fréquents : bradycardie","Effets indésirables : ils sont très fréquents et comprennent la bradycardie, l'asystolie, la pause sinusale et le bloc atrio-ventriculaire{C}. Ils comprennent aussi la tachycardie sinusale (20 %), le flush facial (18 %) et la dyspnée (12 %){C}."),
("Piège d'examen : l'atropine ne supprime pas","Piège d'examen : l'atropine ne peut pas supprimer la bradycardie déclenchée par l'adénosine{C}."),
("L'information professionnelle cite parmi les indications les tachyarythmies","L'information professionnelle cite parmi les indications les tachyarythmies comme la tachycardie paroxystique supraventriculaire{C}. Elle exclut le syndrome de Wolff-Parkinson-White{C}."),
("Autre molécule de la classe : le diltiazem","Autre molécule de la classe : le diltiazem porte le code ATC C08DB01{C}."),
("Posologie de la forme à libération prolongée Isoptin retard 120","Posologie de la forme à libération prolongée Isoptin retard 120 : l'adulte prend un comprimé matin et soir, à environ 12 heures d'intervalle{C}."),
("Contre-indications : choc cardiovasculaire","Contre-indications : elles comprennent le choc cardiovasculaire, le bloc atrio-ventriculaire de degré 2 ou 3 et la maladie du nœud sinusal{C}. Elles comprennent aussi l'insuffisance cardiaque avec fraction d'éjection inférieure à 35 % et la fibrillation ou le flutter avec faisceau accessoire{C}."),
("Contre-indications du métoprolol","Contre-indications du métoprolol : elles comprennent le bloc atrio-ventriculaire de degré 2 ou 3 et l'insuffisance cardiaque décompensée{C}. Elles comprennent aussi la bradycardie inférieure à 50 battements par minute et le syndrome du nœud sinusal sans stimulateur{C}."),
("À long terme, une cohorte de radiofréquence","À long terme, une cohorte de radiofréquence de 1993 à 2021 rapporte 9 blocs atrio-ventriculaires tardifs avec pose de stimulateur{C}. L'incidence est de 0,58 pour 1000 patients-années, et le contrôle du rythme atteint 97 % des patients{C}."),
("Le traitement épisodique « pilule dans la poche »","Le traitement épisodique « pilule dans la poche » par un antiarythmique peut se discuter chez des patients choisis avec des épisodes rares et bien tolérés{C}. Un test sous surveillance précède cette prescription pour exclure les effets indésirables{C}."),
("Dans la cohorte de cardio-obstétrique, 25 %","Dans la cohorte de cardio-obstétrique, 25 % des patientes avec antécédents reçoivent de l'adénosine intraveineuse et 32 % une ablation{C}. Les issues obstétricales et néonatales sont comparables à celles du groupe témoin{C}."),
("L'adénosine n'est à employer que par nécessité absolue","L'adénosine s'emploie uniquement par nécessité absolue pendant l'allaitement{C}."),
("Le consensus européen préfère l'adénosine au vérapamil et au diltiazem chez l'enfant","Le consensus européen préfère l'adénosine au vérapamil et au diltiazem chez l'enfant, car elle présente un meilleur profil dans cette population{C}."),
("L'adénosine s'emploie à la même posologie que chez l'adulte","L'adénosine s'emploie à la même posologie que chez l'adulte{C}."),
("Après une première ablation réussie, la tachycardie récidive","Après une première ablation réussie, la tachycardie peut récidiver chez certains patients{C}."),
("Les critères de guérison sont l'absence de récidive","Les critères de guérison sont l'absence de récidive symptomatique au suivi et le contrôle du rythme. Dans la cohorte de 1993 à 2021, 97 % des patients sont en contrôle de rythme à long terme^wba4ec3-4,wba4ec3-5^."),
("La prévention de la réentrée intranodale se pense","La prévention de la réentrée intranodale se pense à trois niveaux. Le profil décrit au point 2 est celui d'un adulte jeune ou d'âge moyen, souvent une femme, avec un risque de récidive élevé{C}."),
("Chaque piège ci-dessous prend la forme","Chaque piège ci-dessous prend la forme d'une question d'examen. La bonne réponse et sa raison suivent chaque question."),
]
for a,b in P: fix(a,b)
for f in FILES: open(f,'w',encoding='utf-8').write(TXT[f])
